### Инициализация (`i18n.ts`) — **один раз** на процесс

```ts
// packages/i18n/src/i18n.ts
import i18n from 'i18next';
import { initReactI18next } from 'react-i18next';
import * as Localization from 'expo-localization'; // RN
// import { getLocales } from 'expo-localization'; // Web (expo-router) или window.navigator

import en from './locales/en.json';
import ru from './locales/ru.json';

const resources = { en: { translation: en }, ru: { translation: ru } };

const initI18n = async () => {
  const deviceLang = Localization.getLocales?.()[0]?.languageCode ?? 'en';
  const lng = ['en', 'ru'].includes(deviceLang) ? deviceLang : 'en';

  if (!i18n.isInitialized) {
    await i18n
      .use(initReactI18next)
      .init({
        resources,
        lng,
        fallbackLng: 'en',
        interpolation: { escapeValue: false },
        react: { useSuspense: false }, // критично для RN (нет SSR)
        // keySeparator: '.', // дефолт
        // nsSeparator: ':',  // дефолт
      });
  }
  return i18n;
};

export default initI18n;
```

