### Хук-провайдер (`useTranslation.ts`)

```ts
// packages/i18n/src/useTranslation.ts
import { useTranslation as useI18n } from 'react-i18next';
import type { TFunction } from 'i18next';
import type { Resources } from './locales/en.json'; // <-- типы из JSON

export type TranslationKeys = keyof Resources; // "common" | "onboarding" | "tx"

export function useTranslation(ns?: TranslationKeys) {
  const { t, i18n, ready } = useI18n(ns);
  return { t: t as TFunction<Resources, undefined, TranslationKeys>, i18n, ready };
}
```

**Типобезопасность:** `t('onboarding.seedWarning', { count: 12 })` — автодополнение и ошибка TS, если ключ нет в `en.json`.

