  Onboarding: undefined;
  SeedVerify: { words: string[] }; // только идентификаторы/данные для экрана
  SetPin: undefined;
  // Приватные (внутри табов)
  MainTabs: undefined;
  // Модальные / оверлеи
  Send: { token?: string; address?: string }; // опциональные префиллы
  Receive: { token?: string };
  Settings: undefined;
  Security: undefined;
  BackupReminder: undefined;
};

export type TabsParamList = {
  Home: undefined;
  Portfolio: undefined;
  Activity: undefined;
  Settings: undefined;
};

// Тип-хелперы для хуков
import type { CompositeNavigationProp } from '@react-navigation/native';
import type { NativeStackNavigationProp } from '@react-navigation/native-stack';
import type { BottomTabNavigationProp } from '@react-navigation/bottom-tabs';

export type RootNavProp = CompositeNavigationProp<
  NativeStackNavigationProp<RootStackParamList>,
  BottomTabNavigationProp<TabsParamList>
>;

export type TabNavProp = BottomTabNavigationProp<TabsParamList>;
```

**Использование в экранах:**
```tsx
// apps/mobile/src/screens/Send.tsx
import { useNavigation } from '@react-navigation/native';
import type { RootNavProp } from '@shared/navigation/types';

const nav = useNavigation<RootNavProp>();
// nav.navigate('Send', { token: 'USDC', address: '0x...' }) — полностью типизировано
```

**Декларация модуля (чтобы не импортировать типы в каждый файл):**
```ts
// apps/mobile/src/navigation.d.ts
import '@react-navigation/native';
import type { RootStackParamList, TabsParamList } from '@shared/navigation/types';

declare module '@react-navigation/native' {
  export interface RootParamList extends RootStackParamList, TabsParamList {}
}
```

